  <script>
    (() => {
      const root = document.documentElement;
      const toggle = document.getElementById("theme-toggle");

      function setTheme(theme, rememberChoice = false) {
        const isDark = theme === "dark";
        root.dataset.theme = isDark ? "dark" : "light";
        toggle.setAttribute("aria-label", isDark ? "Switch to day mode" : "Switch to night mode");
        toggle.setAttribute("aria-pressed", String(isDark));
        toggle.innerHTML = isDark
          ? '<span aria-hidden="true">☀</span> Night mode'
          : '<span aria-hidden="true">☾</span> Day mode';
        document.querySelector('meta[name="theme-color"]').content = isDark ? "#14142B" : "#FFF8E7";

        if (rememberChoice) {
          try {
            localStorage.setItem("upb-theme", isDark ? "dark" : "light");
          } catch (_) {
            // Theme switching remains available for this visit if storage is unavailable.
          }
        }
      }

      setTheme(root.dataset.theme);

      toggle.addEventListener("click", () => {
        setTheme(root.dataset.theme === "dark" ? "light" : "dark", true);
      });
    })();
  </script>
